"""equine_diseases.py – 馬の疾患データベースと鑑別診断エンジン

獣医学的な馬の一般的疾患をカテゴリ別に整理し、
健康チェックリストの所見からの鑑別診断リスト生成を行う。

分類体系:
  - musculoskeletal: 運動器(骨・関節・腱・靭帯)
  - hoof: 蹄(蹄葉炎、裂蹄、蹄叉腐爛等)
  - respiratory: 呼吸器
  - digestive: 消化器(疝痛、胃潰瘍等)
  - skin: 皮膚(皮膚糸状菌症、蕁麻疹等)
  - eye: 眼
  - neurological: 神経系
  - cardiovascular: 循環器
  - reproductive: 生殖器
  - infectious: 感染症(馬インフルエンザ等)
  - metabolic: 代謝性疾患
  - dental: 歯科
  - toxic: 中毒・毒性
  - foal: 子馬(新生子)
  - immune: 免疫・アレルギー
  - oncology: 腫瘍
  - urinary: 泌尿器
  - misc: その他(外傷・環境)

736疾患 — 17カテゴリ / 211+チェック項目

※ 本データは参考情報であり、獣医師による診断の代替ではありません。
"""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Disease:
    """馬の疾患"""

    id: str  # 一意ID (e.g. "ms_ocd")
    name_ja: str  # 日本語名
    name_en: str  # 英語名
    category: str  # カテゴリ (musculoskeletal, hoof, etc.)
    severity: str  # mild / moderate / severe / critical
    description_ja: str  # 概要
    # 関連する所見キー (チェックリストのキーと対応)
    associated_findings: list[str] = field(default_factory=list)
    # 特徴的な追加情報
    age_predisposition: str = ""  # "young" / "adult" / "senior" / ""
    common_breeds: str = ""  # 好発品種
    urgency: str = ""  # "emergency" / "urgent" / "routine"
    # 推奨検査 (優先度, 日本語名, 英語名) — 優先度1が最優先
    recommended_exams: list[tuple[int, str, str]] = field(default_factory=list)
    # Merck Veterinary Manual 参照リンク
    merck_url: str = ""
    # ---- 拡張臨床情報(獣医師法に触れない一般的な解説) ----
    risk_factors: str = ""  # リスク因子・好発条件
    clinical_signs_detail: str = ""  # 代表的な臨床徴候の詳細
    general_management: str = ""  # 一般的な管理・対処の方向性(診断・処方は含まない)
    prognosis: str = ""  # 一般的な予後
    prevention: str = ""  # 予防策
    # ---- 病態生理・原因・治療プロトコル ----
    etiology: str = ""  # 病因・原因
    pathophysiology: str = ""  # 病態生理
    treatment_protocol: str = ""  # 治療プロトコル(獣医師向け)

    def reference_links(self) -> list[dict[str, str]]:
        """外部参照リンクを生成(症例写真・イラスト付きページへ)"""
        import re as _re
        import urllib.parse as _up

        links: list[dict[str, str]] = []
        if self.name_en:
            # HorseDVM: /disease/[slug] — 写真・イラスト付き疾患ページ
            slug = _re.sub(r"[^a-z0-9]+", "-", self.name_en.lower()).strip("-")
            links.append(
                {
                    "label": "HorseDVM",
                    "url": f"https://horsedvm.com/disease/{slug}",
                    "desc": "症例写真・イラスト付き解説",
                }
            )
            # EquiMed: /diseases-and-conditions/reference/[slug]
            links.append(
                {
                    "label": "EquiMed",
                    "url": f"https://equimed.com/diseases-and-conditions/reference/{slug}",
                    "desc": "疾患百科事典",
                }
            )
        if self.merck_url:
            links.append({"label": "Merck Vet Manual", "url": self.merck_url, "desc": "獣医学マニュアル"})
        elif self.name_en:
            links.append(
                {
                    "label": "Merck Vet Manual",
                    "url": _MERCK + _up.quote(f"equine {self.name_en}"),
                    "desc": "獣医学マニュアル検索",
                }
            )
        return links


