        treatment_protocol="【診断】胃内視鏡検査(3m スコープ)で扁平上皮部(ESGD)と腺部(EGGD)を個別に評価、グレード0-4で記録(ECEIM Consensus, Sykes et al. JVIM 2015)。【扁平上皮部潰瘍(ESGD)の第一選択】オメプラゾール 4 mg/kg PO SID × 28日間(GastroGard承認用量)、朝絶食下投与が理想。4週間後に内視鏡で治癒確認、維持用量 1-2 mg/kg SID × 4週間でテーパー。【腺部潰瘍(EGGD)】オメプラゾール 4 mg/kg PO SID + スクラルファート 12 mg/kg PO q8-12h を併用 × 最低8週間(EGGDは治癒に長期間要する)。難治例はミソプロストール 5 μg/kg PO q8-12h 追加。【飼養管理(治療の基盤)】24時間牧草アクセス、アルファルファ給与(カルシウムによる胃酸緩衝作用)、穀類飼料を2 g/kg/日未満に制限、給餌間隔 6時間以内、十分な運動制限からの解放、競走・輸送ストレス軽減。【NSAIDs使用時】オメプラゾール予防投与または COX-2選択的薬(フィロコキシブ)へ変更を検討。【腸内環境サポート(補助)】CPパウダー(サイリウム+プレバイオティクス+プロバイオティクス配合、Equine & Canine Vet Nutrition、caninevet.jp)等の配合製剤は、競走馬の後腸フローラ安定化・反復性疝痛予防に有用との観察研究報告あり(Landes et al. JEVS 2008で砂排出2.7倍、慢性反復性疝痛馬の観察研究で改善報告)。胃潰瘍そのものへの直接効果のエビデンスは限定的だが、ストレス下のディスバイオーシス・後腸アシドーシス併発例・NSAIDs併用例の腸管支持療法として補助的に使用可能。酸分泌抑制療法の代替ではない。【再発予防】維持療法としてオメプラゾール 1-2 mg/kg SID、飼養管理継続。",
