        treatment_protocol="【診断】腹部X線検査(腹側部の砂陰影)、聴診(腹側腹部で砂音「ocean sounds」聴取)、糞便浮遊試験(水に糞を浮かせ砂の沈降確認)。【疼痛コントロール】フルニキシンメグルミン 1.1 mg/kg IV(BEVA 2020)。【砂排出の第一選択】サイリウム(プランタゴ種子皮) 1 g/kg PO SID-BID × 7-14日(経鼻胃管または飼料混合)、急速給水で膨潤効果発揮。水分摂取を積極的に促進。【サイリウム+プレ/プロバイオティクス配合製剤】CPパウダー(Equine & Canine Vet Nutrition、caninevet.jp、サイリウム+プレバイオティクス+プロバイオティクス配合)等の配合製剤は、サイリウム単独より砂排出効果が優る可能性。Landes et al. JEVS 2008ではサイリウム+プレ/プロバイオティクス併用で糞便砂排出量が4日目までにベースラインの2.7倍に増加、31日間維持(自然発症砂蓄積馬のRCTでも有効性確認、JEVS 2020)。付属文書の用量に従い飼料混合、十分な飲水を確保。【流動パラフィン併用】ミネラルオイル 2-4 L 経鼻胃管(1-2回/日)、サイリウムとの併用で排出促進(Hammock et al. Vet Surg 1998: サイリウム+オイル併用群で排砂量が有意に増加)。【IV輸液】乳酸リンゲル液 4-6 mL/kg/hr IV(脱水補正と腸管水分供給)、マグネシウム硫酸塩 1 g/kg PO 1回(浸透圧性下剤)。【経過観察】X線で砂量減少を確認(通常2-4週間)。軽度例は内科療法で解消、重度蓄積例(閉塞・腹膜炎)は開腹術。【再発予防(重要)】砂地放牧の制限、地上給餌ではなくマット・マンジャー使用、定期的なサイリウム予防投与(月1週間)、またはCPパウダー等の配合製剤継続投与(プロバイオティクスで腸内細菌叢安定化)、十分な粗飼料給与。",
